function confirm(bytes32 _h) returns (bool o_success);
}

contract WalletLibrary is WalletEvents {

struct PendingState {
uint yetNeeded;
uint ownersDone;
uint index;
}

struct Transaction {
address to;
uint value;
bytes data;
}

modifier onlyowner {
if (isOwner(msg.sender))
_;
